WITH nova_marca AS ( INSERT INTO marcas (nome) VALUES ('Magazine Luiza') RETURNING id ), novo_parceiro AS ( INSERT INTO parceiros (marca_id, nome, nome_normalizado) SELECT id, 'Magazine Luiza', 'magazine luiza' FROM nova_marca RETURNING id ), programa_livelo AS ( SELECT id FROM programas WHERE nome = 'Livelo' LIMIT 1 ) INSERT INTO promocoes ( programa_id, parceiro_id, titulo, url_origem, regulamento_texto, data_inicio, data_fim, pontuacao, unidade_pontuacao, marketplace_status, origem, status, hash_promocao ) SELECT programa_livelo.id, novo_parceiro.id, 'Magazine Luiza - 18 pontos por real (TESTE)', 'https://exemplo.com/promocao-teste', 'Regulamento de teste: valido de 01/08 a 31/08, sem necessidade de cupom ou clube.', now(), now() + interval '30 days', 18, 'pontos_por_real', 'PERMITIDO', 'MANUAL', 'PENDENTE', 'teste-manual-001' FROM novo_parceiro, programa_livelo RETURNING id, codigo_amigavel, titulo, pontuacao, status;